-- aar/w3/aar_row_582_draft1.sql
-- DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36), on its order of 22:55 CST 2026-11-23. NOT RUN by W3. For a W1 grade, then insert from seat 36.
-- One ask_aar_snapshots row for ASK 582 (engine manual: write history moved from the body to the log), first pass and second pass batches 1 to 3, and its ask_aar_builders row.
-- Sources: the Wall posts named (heads read by W3 by SQL for this row), audit_log rows 40709, 41033, 41066, 41121 and engine_manual_log (read by SQL), and W3's md_notes for four pair-file md5s, each marked.
-- md5_written lists the pair files as written; grades name the md5 each grade was given on.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (582, '0', 'ASK 582: engine manual write history moved from the body to the log',
  $t$The body of the engine manual holds only what the engine now does; the write history (cards, press times, md5s, grades, readbacks, revert files, "since ASK n" clauses) stands in engine_manual_log, word for word. (first pass: the operator's order of 20:13 CST 2026-11-23, Wall 11200; second pass: plan Wall 11269, its OBJECTIVE line)$t$,
  'in part',
  $t$FIRST PASS: engine manual version 241 written by W3 at 20:28 CST 2026-11-23 on the operator's order of 20:13 CST in the W3 thread: 145 pairs on version 240, 743,498 to 707,670 characters (md5 d0e9efda3280624ce987050bc9568197), the removed text held in log row 210 (audit 40709; Wall 11208; W1 readback MATCH Wall 11209). SECOND PASS, by part after the manual was cut into parts (ASK 583), plan Wall 11269 (W1 PASS WITH CONDITIONS P1 to P3, Wall 11270), three batches, each on its own card in the W3 thread: batch 1 (class A, whole provenance lines; 21 pairs in parts 09.0, 11.0, 11.1) written on the press "Write it" 22:05 CST, versions 248 to 250, log rows 245 to 247, audit 41033 (Wall 11283; W1 readback MATCH Wall 11284); batch 2 (class B, "since ASK n" inside behaviour sentences; 34 pairs in 15 parts) written on the press "Write it" 22:25 CST, versions 251 to 265, log rows 263 to 277, audit 41066 (Wall 11285; W1 readback MATCH Wall 11287); batch 3 (5 leftover card and approval notes and one stale count cut; 16 times written in UTC put in Central; 21 pairs in 8 parts) written on the press "Write all 21" 22:49 CST, versions 266 to 273, log rows 286 to 293, audit 41121 (Wall 11321; W1 readback MATCH Wall 11323). Whole manual after batch 3: version 273, a15d166873cb78a8ab325d0473379c1f, 705,967 characters. IN PART, because: (a) text KEPT in the body under the law and named in the batch 3 README: rulings cited by their time, one-line Why lines, stored cutoffs v_agree_from and v_505_from, price page dates, "Shown by run" lines, and part 10.0's override-card sentence; (b) regrouping entries by subject is a later ASK; (c) no check refuses history in new body text, so the objective holds only as far as each later write follows section 0. MISTAKES ON RECORD: batch 1 draft 1 would have moved the manual's only mention of the live 41147 fault to the log (found by W4, Wall 11273; corrected in draft 2, Wall 11274); batch 3 was written with no separate rolled-back rehearsal (the write call enforced the posted figures; reported to the operator).$t$,
  '11200, 11269',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$20:13 CST 2026-11-23, W3 thread, as quoted at Wall 11200: "make the correct now... move all that maintenance stuff where it should go". Card presses in the W3 thread: "Write it" 22:05 CST (batch 1), "Write it" 22:25 CST (batch 2), "Write all 21" 22:49 CST (batch 3). The first pass was written on the order itself; the record W3 read for this row holds no card for it.$t$::text),
  $j${"answer": "Write all 21", "press_time": "22:49 CST", "thread": "W3", "question": "Write batch 3 of the engine manual clean-up as shown in the card text?", "source": "Wall 11321; audit 41121", "earlier_cards": [{"question": "Write batch 1: move 21 history notes from the engine manual body to its log?", "answer": "Write it", "press_time": "22:05 CST", "source": "audit 41033"}, {"question": "Write batch 2: drop 34 'since ASK' clauses from the engine manual body?", "answer": "Write it", "press_time": "22:25 CST", "source": "audit 41066"}]}$j$::jsonb,
  'W3',
  $j${"path": "Wall 11269 (second pass plan, in the post; no file md5)", "note": "first pass had no separate plan: the draft at Wall 11200 was graded as the plan and the build", "source": "Wall 11200, 11269, 11270"}$j$::jsonb,
  $j$[{"md5": "99dbb904", "path": "manual1123/w3/a582/em_pairs_v241_draft.json", "note": "first pass pairs, draft 1 (commit 26b4794c)", "source": "Wall 11200"}, {"md5": "8f3e7ef6", "path": "manual1123/w3/a582/em_pairs_v241_draft.json", "note": "first pass pairs, draft 2 after W1 C1 (commit d5507ea4); the pairs written as version 241", "source": "Wall 11203; W3 md_notes"}, {"md5": "f5f94007", "path": "manual1123/w3/a582b/ (batch 1 pairs, part 09.0)", "note": "batch 1", "source": "W3 md_notes; Wall 11271"}, {"md5": "27411c9d", "path": "manual1123/w3/a582b/ (batch 1 pairs, part 11.0)", "note": "batch 1", "source": "W3 md_notes; Wall 11271"}, {"md5": "c444460c", "path": "manual1123/w3/a582b/ (batch 1 pairs, part 11.1, draft 2)", "note": "batch 1 draft 2, commit ce324046; draft 1 was f68e88cb", "source": "W3 md_notes; Wall 11274"}, {"md5": "54b9cd13", "path": "manual1123/w3/a582b/b2_pairs_all.json", "note": "batch 2, 34 pairs, commit d88b50c8", "source": "Wall 11279, 11281"}, {"md5": "ea979c3c", "path": "manual1123/w3/a582b/b3_pairs_all.json", "note": "batch 3 draft 1, commit 313b5bb1", "source": "Wall 11290"}, {"md5": "209c5413", "path": "manual1123/w3/a582b/b3_pairs_all_d2.json", "note": "batch 3 with W1 F1 met, commit af0e993f; the pairs written", "source": "Wall 11311, 11312; md5sum by W3"}]$j$::jsonb,
  $j${"copy": "every prior version stays in the tables: engine_manual version 240 (whole text) for the first pass; engine_manual_parts keeps each part's earlier row; the removed text of every pair stands word for word in engine_manual_log", "source": "engine manual section 0 (part 00.1)"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH ONE CONDITION C1 (first pass draft 1)", "wall_id": 11202, "md5_graded": "99dbb904", "verdict_norm": "PASS", "source": "Wall 11202 head"}, {"seat": "W1", "verdict": "C1 MET (first pass draft 2)", "wall_id": 11205, "md5_graded": "8f3e7ef6", "verdict_norm": "PASS", "source": "W3 md_notes naming Wall 11205; the head of 11205 read by W3 for this row shows another item first"}, {"seat": "W1", "verdict": "PASS WITH CONDITIONS P1 to P3 (second pass plan)", "wall_id": 11270, "md5_graded": "none: the plan is the Wall post 11269", "verdict_norm": "PASS", "source": "Wall 11270 head"}, {"seat": "W1", "verdict": "PASS (batch 1 draft 1; superseded)", "wall_id": 11272, "md5_graded": "f68e88cb", "verdict_norm": "PASS", "source": "Wall 11272 head; W3 md_notes for the md5"}, {"seat": "W1", "verdict": "PASS (batch 1 draft 2)", "wall_id": 11276, "md5_graded": "c444460c", "verdict_norm": "PASS", "source": "Wall 11276 head; W3 md_notes for the md5"}, {"seat": "W1", "verdict": "PASS ON THE PAIRS WITH ONE CONDITION A1 (batch 2); A1 confirmed Wall 11284", "wall_id": 11281, "md5_graded": "54b9cd13", "verdict_norm": "PASS", "source": "Wall 11281 head; Wall 11284 head"}, {"seat": "W1", "verdict": "PASS WITH F1 (batch 3 draft 1)", "wall_id": 11302, "md5_graded": "ea979c3c", "verdict_norm": "PASS", "source": "W1 relay naming Wall 11302"}, {"seat": "W1", "verdict": "F1 MET (batch 3 pairs as written)", "wall_id": 11312, "md5_graded": "209c5413", "verdict_norm": "PASS", "source": "Wall 11312 head"}]$j$::jsonb,
  ARRAY['8f3e7ef6','f5f94007','27411c9d','c444460c','54b9cd13','209c5413'], '[40709, 41033, 41066, 41121]'::jsonb,
  $j$[{"kind": "database table row", "name": "engine_manual version 241", "before": "version 240, 8534e5745c15afcf72d8277103aefd08, 743,498", "after": "d0e9efda3280624ce987050bc9568197, 707,670"}, {"kind": "database table rows", "name": "engine_manual_parts, batch 1", "before": "09.0, 11.0, 11.1 at their earlier versions", "after": "versions 248, 249, 250"}, {"kind": "database table rows", "name": "engine_manual_parts, batch 2", "before": "15 parts at their earlier versions", "after": "versions 251 to 265 (whole manual 213932548322e0d6db4562768135eb2b, 706,382)"}, {"kind": "database table rows", "name": "engine_manual_parts, batch 3", "before": "08.0 v242, 09.1 v255, 09.7 v259, 09.8 v242, 10.0 v260, 11.0 v261, 11.1 v250, 12.0 v262", "after": "versions 266 to 273 (whole manual a15d166873cb78a8ab325d0473379c1f, 705,967)"}, {"kind": "database table rows", "name": "engine_manual_log", "before": "no rows for these versions", "after": "rows 210; 245 to 247; 263 to 277; 286 to 293"}]$j$::jsonb,
  $j$[{"name": "batch 2 and batch 1: rolled-back rehearsal of the writes", "result": "figures posted before each card and confirmed by W1", "source": "Wall 11271, 11279, 11283, 11284"}, {"name": "batch 3: read-only fold of the 21 pairs over the latest row of each part", "result": "every pair counted once; 11.0 37,965 and whole manual 705,967, equal to W1's expected figures", "source": "Wall 11311, 11312"}, {"name": "batch 3 write call", "result": "each part written with its expected md5 and length; a final check that raises unless the whole manual reads version 273 a15d1668 705,967; no separate rolled-back rehearsal", "source": "Wall 11321"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (version 241)", "wall_id": 11209}, {"seat": "W1", "result": "MATCH (batch 1)", "wall_id": 11284}, {"seat": "W1", "result": "MATCH (batch 2)", "wall_id": 11287}, {"seat": "W1", "result": "MATCH (batch 3: eight parts, whole manual version 273, log rows 286 to 293, audit 41121)", "wall_id": 11323}]$j$::jsonb,
  $j${"case": "NO RUN MARK: a manual text change; no engine effect.", "source": "plan Wall 11269"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "this ASK is the manual change: versions 241, 248 to 250, 251 to 265, 266 to 273; whole manual version 273 a15d166873cb78a8ab325d0473379c1f 705,967 at the end of batch 3"}$j$::jsonb,
  'read back', $j$[11200, 11202, 11203, 11205, 11208, 11209, 11269, 11270, 11271, 11272, 11273, 11274, 11276, 11279, 11281, 11283, 11284, 11285, 11287, 11290, 11302, 11311, 11312, 11321, 11323]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W3'], $j$[{"seat": "W3", "what": "drafted and wrote the four manual writes of ASK 582 (version 241; batches 1 to 3)", "wall_id": 11321}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
